package org.jlinalg.cli;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class FumaAssociationCliTest {
    @TempDir Path directory;
    private String message;
    private int run(String... args){var output=new ByteArrayOutputStream();var error=new ByteArrayOutputStream();try(var out=new PrintStream(output,true,StandardCharsets.UTF_8);var err=new PrintStream(error,true,StandardCharsets.UTF_8)){int code=FumaToolsCli.run(args,out,err);message=output.toString(StandardCharsets.UTF_8)+error.toString(StandardCharsets.UTF_8);return code;}}
    private int run(Map<String,String> options){var args=new ArrayList<String>();options.forEach((k,v)->{args.add("--"+k);args.add(v);});return run(args.toArray(String[]::new));}
    private Map<String,String> options(String name)throws Exception{return FumaAssociationTestData.options(directory.resolve(name));}
    private Path out(Map<String,String> options){return Path.of(options.get("out"));}
    private Map<?,?> session(Path path)throws Exception{return AdmixtureInputs.decode(Files.readAllBytes(path.resolve("session.json")));}
    private List<Map<String,String>> table(Path path)throws Exception {var lines=Files.readAllLines(path);var header=lines.get(0).split("\t",-1);var result=new ArrayList<Map<String,String>>();for(String line:lines.subList(1,lines.size())){var fields=line.split("\t",-1);assertEquals(header.length,fields.length);var row=new LinkedHashMap<String,String>();for(int i=0;i<header.length;i++)row.put(header[i],fields[i]);result.add(row);}return result;}
    private void replace(Map<String,String> options,String key,String before,String after)throws Exception{Path path=Path.of(options.get(key));String text=Files.readString(path);assertTrue(text.contains(before),before);Files.writeString(path,text.replace(before,after));}
    private void failed(Map<String,String> options)throws Exception{assertEquals(2,run(options),message);assertTrue(Files.readString(out(options).resolve("WARNINGS.md")).contains("Required action"));assertTrue(Files.readString(out(options).resolve("analysis-status.json")).contains("failed"));assertFalse(Files.exists(out(options).resolve("all-tests.tsv")));assertFalse(Files.exists(out(options).resolve("target-decisions.tsv")));assertTrue(Files.isDirectory(out(options).resolve("partial")));}
    @Test void completeLedgersRetainEveryTestUnionContributorAndTargetDisposition()throws Exception {
        var o=options("complete");assertEquals(0,run(o),message);var s=session(out(o));assertEquals(11,((Number)s.get("test_rows")).intValue());assertEquals(3,((Number)s.get("known_union_rows")).intValue());assertEquals(1,((Number)s.get("known_link_rows")).intValue());assertEquals(6,((Number)s.get("baseline_coverage_rows")).intValue());
        var targets=table(out(o).resolve("target-decisions.tsv"));assertEquals(List.of("KNOWN","NOVEL_RELATIVE_TO_BASELINES","UNASSESSABLE_BASELINE","TARGET_NOT_SELECTED"),targets.stream().map(r->r.get("status")).toList());assertEquals(List.of("1","0","0","NA"),targets.stream().map(r->r.get("matched_known_tests")).toList());
        var tests=table(out(o).resolve("all-tests.tsv"));assertEquals(11,tests.size());assertEquals("2",tests.get(0).get("tests_source_line"));assertEquals("12",tests.get(10).get("tests_source_line"));assertEquals("0.004",tests.get(0).get("adjusted_p"));assertEquals(3,table(out(o).resolve("family-audit.tsv")).size());assertEquals(6,table(out(o).resolve("family-members.tsv")).size());assertEquals(3,table(out(o).resolve("known-contributors.tsv")).size());assertEquals(List.of(Map.of("target_input_row","8","baseline_input_row","1")),table(out(o).resolve("known-links.tsv")));assertTrue(message.contains("REVIEW REQUIRED"));
    }
    @Test void acrossTraitProjectionChangesLinksButNeverCorrectionFamilies()throws Exception {
        var exact=options("exact");assertEquals(0,run(exact),message);var all=options("all");all.put("matching","gene-across-traits");assertEquals(0,run(all),message);assertEquals(table(out(exact).resolve("all-tests.tsv")),table(out(all).resolve("all-tests.tsv")));assertEquals(table(out(exact).resolve("family-audit.tsv")),table(out(all).resolve("family-audit.tsv")));assertEquals(2,table(out(all).resolve("known-links.tsv")).size());assertTrue(table(out(all).resolve("known-union.tsv")).stream().allMatch(r->r.get("matched_trait").equals("NA")));assertTrue(Files.readString(out(all).resolve("WARNINGS.md")).contains("GENE UNION ACROSS TRAITS"));
    }
    @Test void sourceBuildsAndAnnotationsRemainIndependentMetadataForGeneIdJoins()throws Exception {
        var o=options("builds");o.put("build","analysis-only-label");assertEquals(0,run(o),message);var sources=table(out(o).resolve("analysis-sources.tsv"));assertEquals(List.of("GRCh37","GRCh38","GRCh38"),sources.stream().map(r->r.get("genome_build")).toList());assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("SOURCE ANNOTATION/BUILD DIFFERENCES"));assertEquals("analysis-only-label",session(out(o)).get("analysis_build_metadata"));
    }
    @Test void namespaceMismatchesRefuseJoinsAndGeneUnionAllowsSeparateTraitMetadata()throws Exception {
        var o=options("gene-namespace");replace(o,"sources","M-v1\tgene-v1","M-v1\tother-gene");failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("gene namespaces differ"));o=options("trait-namespace");replace(o,"sources","M-v1\tgene-v1\ttrait-v1","M-v1\tgene-v1\tother-trait");failed(o);o.put("matching","gene-across-traits");o.put("out",out(o).resolveSibling("pooled").toString());assertEquals(0,run(o),message);assertEquals("other-trait",table(out(o).resolve("analysis-sources.tsv")).get(0).get("trait_namespace"));
    }
    @Test void incompleteAndUndeclaredFamilyMembersAreRejectedWithoutPartialSelection()throws Exception {
        var o=options("incomplete");replace(o,"members","A\tT1\tmagma\t2","A\tT1\tmagma\t3");failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("Incomplete declared family"));o=options("unknown-member");replace(o,"members","A\tT1\tmagma\t2","unknown\tT1\tmagma\t2");failed(o);o=options("undeclared-domain");replace(o,"tests","a1\tG1\tT1","a1\tG1\tother");failed(o);
    }
    @Test void missingBaselineEvidenceRemainsUnassessableAndAllRowsAreRetained()throws Exception {
        var o=options("missing");replace(o,"families","A\tM\tP_VALUE\tBH\tERROR","A\tM\tP_VALUE\tBH\tEXCLUDE");replace(o,"tests","a3\tG3\tT2\tmagma\t0.03","a3\tG3\tT2\tmagma\tNA");o.put("absence","selected-reference");assertEquals(0,run(o),message);assertEquals("UNASSESSABLE_BASELINE",table(out(o).resolve("target-decisions.tsv")).get(1).get("status"));var family=table(out(o).resolve("family-audit.tsv")).get(0);assertEquals("4",family.get("actual_rows"));assertEquals("3",family.get("available_rows"));assertEquals("3",family.get("computed_adjustment_size"));assertEquals("NA",table(out(o).resolve("all-tests.tsv")).get(2).get("adjusted_p"));
    }
    @Test void suppliedAdjustedValuesRemainUnchangedWithUnknownOriginalDenominator()throws Exception {
        var o=options("supplied");replace(o,"families","A\tM\tP_VALUE\tBH","A\tM\tP_VALUE\tSUPPLIED_ADJUSTED");assertEquals(0,run(o),message);var f=table(out(o).resolve("family-audit.tsv")).get(0);assertEquals("4",f.get("available_rows"));assertEquals("NA",f.get("computed_adjustment_size"));var tests=table(out(o).resolve("all-tests.tsv"));for(int i=0;i<4;i++)assertEquals(tests.get(i).get("input_value"),tests.get(i).get("adjusted_p"));assertEquals("KNOWN",table(out(o).resolve("target-decisions.tsv")).get(1).get("status"));
    }
    @Test void finiteLogUnderflowAndExplicitReportedZerosRemainDistinct()throws Exception {
        var o=options("logs");replace(o,"families","A\tM\tP_VALUE\tBH\tERROR\tERROR","A\tM\tNATURAL_LOG\tBH\tERROR\tALLOW_REPORTED");replace(o,"tests","magma\t0.001","magma\t-1000");replace(o,"tests","magma\t0.04","magma\t-Inf");replace(o,"tests","magma\t0.03","magma\t-1");replace(o,"tests","magma\t0.9","magma\t0");assertEquals(0,run(o),message);var tests=table(out(o).resolve("all-tests.tsv"));assertEquals("0.0",tests.get(0).get("adjusted_p"));assertTrue(Double.isFinite(Double.parseDouble(tests.get(0).get("adjusted_ln_p"))));assertEquals("-Inf",tests.get(1).get("adjusted_ln_p"));var family=table(out(o).resolve("family-audit.tsv")).get(0);assertEquals("1",family.get("reported_zeros"));assertEquals("1",family.get("adjusted_probability_underflows"));
    }
    @Test void decimalUnderflowNonfiniteAndMalformedValuesAreNeverSilentlyRoundedOrMissing()throws Exception {
        int i=0;for(String value:List.of("1e-1000","-1e-1000","NaN","Infinity","1e9999"," 0.01","0.01 ","","null","0x1.0p-2")){var o=options("bad-value-"+(i++));replace(o,"tests","magma\t0.001","magma\t"+value);failed(o);}var o=options("reported-zero");replace(o,"tests","magma\t0.001","magma\t0");failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("ALLOW_REPORTED"));
    }
    @Test void inclusiveCutoffUsesSourcePrecisionAndPreservesAdjacentBinary64Values()throws Exception {
        var o=options("cutoff");replace(o,"families","C\tT\tP_VALUE\tBH","C\tT\tP_VALUE\tSUPPLIED_ADJUSTED");replace(o,"tests","class1\t0.001","class1\t"+Math.nextDown(.05));replace(o,"tests","class2\t0.002","class2\t0.05");replace(o,"tests","class1\t0.03","class1\t"+Math.nextUp(.05));assertEquals(0,run(o),message);var rows=table(out(o).resolve("all-tests.tsv"));assertEquals(List.of("true","true","false","false"),rows.subList(7,11).stream().map(r->r.get("selected")).toList());assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("CUTOFF ROUNDING REVIEW"));
    }
    @Test void duplicateHypothesesRequireExplicitPolicyAndKeepAllContributorAndLinkRows()throws Exception {
        var o=options("duplicates");replace(o,"tests","a2\tG2\tT1\tmagma\t0.04","a2\tG1\tT1\tmagma\t0.001");failed(o);replace(o,"families","A\tM\tP_VALUE\tBH\tERROR\tERROR\tERROR","A\tM\tP_VALUE\tBH\tERROR\tERROR\tRETAIN");o.put("out",out(o).resolveSibling("retained").toString());assertEquals(0,run(o),message);assertEquals("1",table(out(o).resolve("all-tests.tsv")).get(1).get("duplicate_of_input_row"));assertEquals(2,table(out(o).resolve("known-contributors.tsv")).stream().filter(r->r.get("union_row").equals("1")).count());assertEquals(2,table(out(o).resolve("known-links.tsv")).stream().filter(r->r.get("target_input_row").equals("8")).count());
    }
    @Test void carrierRelativePathsAndCRLFSnapshotsRetainExtraColumnsByteForByte()throws Exception {
        var o=options("carrier");Path base=out(o).getParent();for(String key:List.of("sources","families","members","tests")){Path p=Path.of(o.get(key));Files.writeString(p,Files.readString(p).replace("\n","\r\n"));o.put(key,p.getFileName().toString());}o.put("out","analysis");Path carrier=FumaAssociationTestData.carrier(base.resolve("options.json"),o);assertEquals(0,run("--known-options-file",carrier.toString()),message);var ledger=table(base.resolve("analysis/resource-ledger.tsv"));assertEquals(5,ledger.size());for(var row:ledger){Path source=Path.of(row.get("source")),copy=base.resolve("analysis").resolve(row.get("snapshot"));assertArrayEquals(Files.readAllBytes(source),Files.readAllBytes(copy));assertEquals(FollowupSupport.hash(source),row.get("sha256"));}assertTrue(Files.readString(base.resolve("analysis/source-inputs/i0005.raw")).contains("α\r\n"));
    }
    @Test void everyInputAndEvidenceBudgetRefusesCompleteResultsRatherThanTruncating()throws Exception {
        for(var entry:Map.of("max-rows","22","max-cells","10","max-evidence","1","max-operations","1","max-output-rows","1").entrySet()){var o=options(entry.getKey());o.put(entry.getKey(),entry.getValue());failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("exceeded"));}
    }
    @Test void snapshotFileAndScientificByteBudgetsKeepProminentFailureDiagnostics()throws Exception {
        for(String key:List.of("max-bytes","max-snapshot-bytes","max-output-bytes")){var o=options(key);o.put(key,"1");failed(o);assertTrue(Files.isRegularFile(out(o).resolve("session.json")));assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("partial/"));}
    }
    @Test void lineAndHeaderColumnBoundsApplyBeforeUnboundedParsing()throws Exception {
        var o=options("long-input");replace(o,"tests","α","x".repeat(1000));o.put("max-line-bytes","512");failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("input line exceeds"));o=options("long-output");o.put("max-line-bytes","256");failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("emitted association row"));o=options("columns");var columns=new ArrayList<String>();for(int i=0;i<257;i++)columns.add("x"+i);Files.writeString(Path.of(o.get("tests")),String.join("\t",columns)+"\n");failed(o);
    }
    @Test void malformedUtf8HeadersFieldsAndMemberCountsHaveSourceContext()throws Exception {
        var o=options("utf8");Files.write(Path.of(o.get("tests")),new byte[]{(byte)0xc3,(byte)0x28});failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("Invalid UTF-8"));int i=0;for(String header:List.of("family\ttest_id\tgene\ttrait\tcontext\n","family\ttest_id\tgene\ttrait\tcontext\tvalue\tvalue\n")){o=options("header-"+(i++));Files.writeString(Path.of(o.get("tests")),header);failed(o);assertTrue(Files.readString(out(o).resolve("session.json")).contains("association-tests"));}for(String value:List.of("-1","1.5","2147483648")){o=options("member-"+(i++));replace(o,"members","magma\t2","magma\t"+value);failed(o);}o=options("control");replace(o,"tests","α","bad\u0000");failed(o);
    }
    @Test void unknownMissingAndInvalidPoliciesDoNotUsePaperDefaults()throws Exception {
        for(String key:List.of("cutoff","matching","absence","gene-namespace","members")){var o=options("missing-"+key);o.remove(key);assertEquals(2,run(o),message);assertFalse(Files.exists(out(o)));assertTrue(message.contains("Required action"));}for(var entry:Map.of("cutoff","0","matching","auto","absence","default","timeout","0").entrySet()){var o=options("invalid-"+entry.getKey());o.put(entry.getKey(),entry.getValue());failed(o);}var o=options("family-default");replace(o,"families","P_VALUE\tBH","P_VALUE\tdefault");failed(o);
    }
    @Test void recursiveNonstringUnknownAndOversizedCarriersFailBeforeCreatingOutput()throws Exception {
        for(String key:List.of("known-options-file","unknown","max-rows")){var o=options("carrier-"+key);var values=new LinkedHashMap<String,Object>(o);values.put(key,key.equals("max-rows")?10:"bad");Path carrier=FumaAssociationTestData.carrier(directory.resolve(key+".json"),values);assertEquals(2,run("--known-options-file",carrier.toString()),message);assertFalse(Files.exists(out(o)));}Path large=directory.resolve("large.json");Files.writeString(large," ".repeat(1048577));assertEquals(2,run("--known-options-file",large.toString()),message);assertTrue(message.contains("oversized"));
    }
    @Test void directOverridesAreExplicitAndExistingOutputsRemainIntact()throws Exception {
        var o=options("override");Path carrier=FumaAssociationTestData.carrier(directory.resolve("options.json"),o),actual=directory.resolve("actual");assertEquals(0,run("--known-options-file",carrier.toString(),"--out",actual.toString()),message);assertFalse(Files.exists(out(o)));assertTrue(Files.exists(actual.resolve("all-tests.tsv")));Files.writeString(actual.resolve("sentinel"),"retained");assertEquals(2,run("--known-options-file",carrier.toString(),"--out",actual.toString()),message);assertEquals("retained",Files.readString(actual.resolve("sentinel")));assertEquals(2,run("--known-options-file",carrier.toString(),"--method","wrong"),message);
    }
    @Test void originalAndSnapshotHashChangesAreDetectedAndCancellationIsCooperative()throws Exception {
        for(boolean snapshot:List.of(false,true)){Path base=directory.resolve("verify-"+snapshot);Files.createDirectory(base);Path source=base.resolve("source.tsv");Files.writeString(source,"A\n1\n");Path bundle=base.resolve("bundle");Files.createDirectory(bundle);var input=new FumaAssociationInputs(bundle,new FumaAssociationInputs.Limits(10000,100,1024,1000,10000,10000,100),()->{});Path copy=input.capture(source,"test",10000);Files.writeString(snapshot?copy:source,"A\n2\n");assertThrows(Exception.class,input::verify);}Path bundle=directory.resolve("cancel");Files.createDirectory(bundle);var checks=new AtomicInteger();var input=new FumaAssociationInputs(bundle,new FumaAssociationInputs.Limits(10000,100,1024,1000,10000,10000,100),()->{checks.incrementAndGet();throw new IllegalStateException("cancelled");});assertThrows(IllegalStateException.class,()->input.capture(directory.resolve("unused"),"test",10000));assertEquals(1,checks.get());
    }
    @Test void allScientificBytesAndRowsAreAccountedAndUnicodeCarrierPathsWork()throws Exception {
        var o=options("日本語-data");o.put("out",directory.resolve("β-output/結果").toString());Path carrier=FumaAssociationTestData.carrier(directory.resolve("ascii.json"),o);assertEquals(0,run("--known-options-file",carrier.toString()),message);long bytes,rows;try(var files=Files.walk(out(o))){bytes=files.filter(Files::isRegularFile).filter(p->p.getFileName().toString().endsWith(".tsv")||p.getParent().getFileName().toString().equals("source-inputs")).mapToLong(p->{try{return Files.size(p);}catch(Exception e){throw new IllegalStateException(e);}}).sum();}try(var files=Files.list(out(o))){rows=files.filter(p->p.getFileName().toString().endsWith(".tsv")&&!p.getFileName().toString().equals("resource-ledger.tsv")).mapToLong(p->{try{return Files.readAllLines(p).size()-1;}catch(Exception e){throw new IllegalStateException(e);}}).sum();}assertEquals(bytes,((Number)session(out(o)).get("scientific_files_and_snapshot_bytes")).longValue());assertEquals(rows,((Number)session(out(o)).get("scientific_result_rows")).longValue());
    }
    @Test void independentParentAssociationStageCompletesAfterAnotherNativeStageFails()throws Exception {
        var o=options("parent-failure");Path base=out(o).getParent(),recipe=FumaAssociationTestData.parent(base,o,Map.of("variant_annotation",Map.of("build","GRCh37")));assertEquals(2,run("--workflow-options-file",recipe.toString()),message);assertTrue(Files.isRegularFile(base.resolve("workflow/known-associations/all-tests.tsv")));assertTrue(Files.readString(base.resolve("workflow/analysis-status.json")).contains("failed"));var journal=Files.readString(base.resolve("workflow/workflow-journal.json"));assertTrue(journal.indexOf("variant-annotation")<journal.indexOf("known-associations"));
    }
    @Test void independentParentAssociationStageCompletesAfterOriginalMagmaIsSkipped()throws Exception {
        var o=options("parent-skip");Path base=out(o).getParent();var annotate=Map.of("method","annotate","home",base.resolve("missing-home").toString(),"snps",base.resolve("missing-snps").toString(),"genes",base.resolve("missing-genes").toString());Path recipe=FumaAssociationTestData.parent(base,o,Map.of("magma_annotate",annotate));assertEquals(3,run("--workflow-options-file",recipe.toString()),message);assertTrue(Files.isRegularFile(base.resolve("workflow/known-associations/all-tests.tsv")));assertTrue(Files.readString(base.resolve("workflow/magma-annotation/WARNINGS.md")).contains("Required action"));assertTrue(Files.readString(base.resolve("workflow/analysis-status.json")).contains("skip"));
    }
    @Test void parentRejectsMethodBuildAndRecursiveCarrierOverridesBeforeOutput()throws Exception {
        for(String key:List.of("method","build","known-options-file")){var o=options("parent-invalid-"+key);o.put(key,"wrong");Path base=out(o).getParent(),recipe=FumaAssociationTestData.parent(base,o,Map.of());assertEquals(2,run("--workflow-options-file",recipe.toString()),message);assertFalse(Files.exists(base.resolve("workflow")));}
    }
    @Test void emptyBaselineFamiliesAndMissingTargetsHaveExplicitNonNovelStates()throws Exception {
        var o=options("empty-baseline");replace(o,"members","B\tT1\tbulk\t1","B\tT1\tbulk\t0");replace(o,"members","B\tT2\tbulk\t2","B\tT2\tbulk\t0");Path path=Path.of(o.get("tests"));Files.writeString(path,String.join("\n",Files.readAllLines(path).stream().filter(line->!line.startsWith("B\t")).toList())+"\n");replace(o,"families","C\tT\tP_VALUE\tBH\tERROR","C\tT\tP_VALUE\tBH\tEXCLUDE");replace(o,"tests","class2\t0.002","class2\tNA");assertEquals(0,run(o),message);var targets=table(out(o).resolve("target-decisions.tsv"));assertEquals("KNOWN",targets.get(0).get("status"));assertEquals("MISSING_TARGET_VALUE",targets.get(1).get("status"));assertEquals("UNASSESSABLE_BASELINE",targets.get(2).get("status"));assertEquals("0",table(out(o).resolve("family-audit.tsv")).get(1).get("actual_rows"));
    }
    @Test void helpExposesExplicitFamiliesMissingnessAndRelativeNovelty(){assertEquals(0,run("--method","known-associations","--help"),message);assertTrue(message.contains("--matching gene-trait|gene-across-traits"));assertTrue(message.contains("computed_adjustment_size=NA"));assertTrue(message.contains("UNASSESSABLE_BASELINE"));assertEquals(0,run("--help"),message);assertTrue(message.contains("--method known-associations --help"));}
}
